<?php
use EIPSI\ExternalApi as A;
function a1_wait($path){$deadline=microtime(true)+20;while(!file_exists($path)){if(microtime(true)>$deadline)throw new RuntimeException('API1 barrier timed out');usleep(10000);}}
function a1_spawn($input){$dir='/tmp/eipsi-api1-'.bin2hex(random_bytes(8));mkdir($dir,0700);$pipes=array();$p=proc_open(array(PHP_BINARY,__DIR__.'/worker.php',$dir),array(0=>array('pipe','r'),1=>array('file',$dir.'/stdout','w'),2=>array('file',$dir.'/stderr','w')),$pipes);a1_assert(is_resource($p));fwrite($pipes[0],json_encode($input));fclose($pipes[0]);a1_wait($dir.'/attempt');return array('process'=>$p,'dir'=>$dir);}
function a1_join(&$job){a1_wait($job['dir'].'/result.json');$r=json_decode(file_get_contents($job['dir'].'/result.json'),true);a1_assert(proc_close($job['process'])===0);$job['process']=null;return$r;}
function a1_remove($job){if(!$job)return;if(is_resource($job['process']))proc_terminate($job['process']);foreach(glob($job['dir'].'/*')as$f)unlink($f);rmdir($job['dir']);}
a1_case('Concurrent list waits for a committed revocation before authorizing',function()use($store){$k=a1_key();$job=null;try{$store->transaction(function()use($store,$k,&$job){$store->key($k['key']['id'],true);$job=a1_spawn(array('op'=>'list','secret'=>$k['secret']));usleep(100000);a1_assert(!file_exists($job['dir'].'/result.json'),'Read escaped its key lock');$store->rows($store->prepare('UPDATE '.$store->table('keys').' SET revoked_at=%d,revision=revision+1 WHERE id=%s',time(),$k['key']['id']));});$r=a1_join($job);a1_assert($r['status']===401&&$r['code']==='eipsi_external_unauthorized');}finally{a1_remove($job);}});
a1_case('Concurrent detail cannot use a grant removed before its authorization snapshot',function()use($store,$a){$k=a1_key();$job=null;try{$store->transaction(function()use($store,$k,$a,&$job){$store->key($k['key']['id'],true);$job=a1_spawn(array('op'=>'detail','secret'=>$k['secret'],'code'=>$a['code']));usleep(100000);a1_assert(!file_exists($job['dir'].'/result.json'));$store->rows($store->prepare('DELETE FROM '.$store->table('grants').' WHERE key_id=%s AND study_id=%s',$k['key']['id'],$a['id']));$store->rows($store->prepare('UPDATE '.$store->table('keys').' SET revision=revision+1 WHERE id=%s',$k['key']['id']));});$r=a1_join($job);a1_assert($r['status']===404&&$r['code']==='eipsi_external_study_unavailable');}finally{a1_remove($job);}});
a1_case('Concurrent hard delete permits an earlier read snapshot but later reads cannot see it',function()use($store,$wpdb){$s=a1_new('RACE_DELETE');$k=a1_key(array($s['id']));$delete=null;$read=null;try{
 $store->transaction(function()use($store,$wpdb,$s,$k,&$delete,&$read){$store->row($store->prepare('SELECT id FROM `'.$wpdb->prefix.'eipsi_engine_study_versions` WHERE id=%s FOR UPDATE',$s['version']));$delete=a1_spawn(array('op'=>'delete','study'=>$s['id']));usleep(100000);a1_assert(!file_exists($delete['dir'].'/result.json'));$read=a1_spawn(array('op'=>'list','secret'=>$k['secret']));$r=a1_join($read);a1_assert($r['status']===200&&a1_codes($r['data'])===array($s['code']),'Earlier snapshot was incoherent');});
 $r=a1_join($delete);a1_assert($r['status']===200);a1_assert(a1_page($k)['items']===array());a1_error(function()use($k,$s){a1_detail($k,$s['code']);},404,'eipsi_external_study_unavailable');
 }finally{a1_remove($delete);a1_remove($read);}
});
